  .searchicon:after{content:"";position:absolute;width:9px;height:2px;background:white;right:-7px;bottom:-4px;transform:rotate(48deg)}
  .adtop{height:232px;display:flex;justify-content:center;align-items:flex-start;padding-top:22px;background:white}
