  .sexbuttons{display:flex;gap:4px}
  .sexbuttons button{height:40px;min-width:90px;border:1px solid #d9e0e3;background:#eaf3f7;color:#515a60}
  .sexbuttons button.selected{background:#3ec8c6;color:white;border-color:#3ec8c6}
  .continue-row{height:64px;border-top:1px solid #e5e5e5;display:flex;align-items:center;justify-content:space-between;padding:0 24px}
