  .stepbtn.next{background:#299fd0;color:#fff;border:0}
  .stepbtn:disabled{background:#e4e4e4;color:#fff;cursor:default}
  .stepbtn .arrow{font-size:23px;float:right;line-height:20px}
  .stepbtn.previous .arrow{float:left;margin-right:22px}
  .symptom-layout{display:grid;grid-template-columns:440px 1fr;gap:22px;min-height:515px;padding:30px 30px 18px}
  .prompt{font-size:25px;color:#51515b;margin:8px 0 20px}
  .searchwrap{position:relative}
  .symptom-input{height:62px;width:100%;padding:0 24px;border:1px solid #cfcfd2;box-shadow:0 2px 5px #00000013;color:#333;font-size:17px}
  .symptom-input::placeholder{color:#c5c5ca}
  .suggestions{display:none;position:absolute;z-index:4;top:61px;left:0;width:100%;max-height:315px;overflow:auto;background:#fff;border:1px solid #ddd;box-shadow:0 3px 8px #0002}
  .suggestions.show{display:block}
  .suggestion{height:48px;padding:0 18px;display:flex;align-items:center;justify-content:space-between;font-size:16px}
  .suggestion .add{border:0;background:#e8f1f5;color:#8195a0;font-size:11px;padding:5px 9px}
