  .emptyicon{width:58px;height:73px;border:2px solid #d8e3e5;border-radius:8px;margin-bottom:22px;position:relative}
  .emptyicon:before{content:"✓  ✓";position:absolute;top:15px;left:8px;line-height:20px;color:#b6cbcf;font-size:13px}
  .mylist{display:block;padding:22px 26px;margin-top:80px;height:auto;min-height:170px}
  .mylist h3{font-size:17px;font-weight:400;margin:0 0 15px}
  .myitem{padding:13px 3px;border-bottom:1px solid #e4e4e4;font-size:14px;color:#53616b}
  .delete{float:right;border:0;background:none;color:#aaa}
  .bodyarea{height:440px;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center}
  .human{height:420px;width:300px;opacity:.78}
  .bodytools{position:absolute;right:0;top:38px;display:flex;flex-direction:column;gap:9px}
  .bodytools button{width:46px;height:44px;background:#fff;border:1px solid #eee;color:#9ba5a9;font-size:12px}
  .bodytools button:hover{border-color:var(--teal)}
  .info-copy{border-top:1px solid #d9dfe2;margin-top:75px;padding-top:48px;font-size:16px;line-height:1.45;color:#38383e}
  .info-copy p{margin:0 0 16px}
  .info-copy a{color:#1889b6;font-weight:bold;text-decoration:none}
  .sidead{padding-top:44px}
  .sidead .adbox{width:340px;height:260px}
  .modalshade{display:none;position:fixed;inset:0;background:rgba(35,36,39,.58);z-index:20;align-items:flex-start;justify-content:center;padding-top:140px}
  .modalshade.open{display:flex}
  .modal{width:565px;background:#fff;box-shadow:0 3px 10px #0004;padding:54px 40px 34px;position:relative;text-align:center}
  .modal-kicker{font-size:14px;color:#888;margin-bottom:12px}
  .modal h2{font-size:22px;margin:0 0 30px;color:#4d4b52}
  .choices{height:475px;overflow-y:auto;text-align:left;padding:0 5px 0 10px}
  .choice{height:79px;display:flex;align-items:center;gap:20px;font-size:18px}
  .choice input{appearance:none;width:24px;height:24px;border:1px solid #c8c8c8;border-radius:3px;margin:0;flex:none}
  .choice input:checked{background:#39c9c7;border-color:#39c9c7}
  .choice input:checked:after{content:"✓";display:block;color:white;text-align:center;font-weight:bold;line-height:22px}
  .modal-done{height:64px;width:100%;background:#ccc;border:0;color:#fff;margin-top:16px}
  .modal-done.enabled{background:#119de0}
  .skip{border:0;background:none;color:#358bb2;margin-top:19px;font-size:16px}
  .closemodal{display:none}
  .results{padding:42px 60px 35px;min-height:650px}
  .result-title{font-size:20px;margin-bottom:18px}
  .resultcols{display:grid;grid-template-columns:1fr 1fr;gap:55px}
  .condition{display:block;text-align:left;width:100%;border:1px solid #d4e5e8;background:#effafa;padding:18px;margin-bottom:8px;color:#555}
  .condition strong{display:block;font-size:17px;margin-bottom:8px}
  .match{color:#35bdbb;font-size:14px}
  .result-summary{font-size:15px;line-height:1.55;border-top:1px solid #ddd;padding-top:12px}
  .result-summary div{padding:10px 0;border-bottom:1px solid #ddd}
  .details{padding:34px 46px;min-height:980px;display:grid;grid-template-columns:300px 1fr;gap:38px}
  .detail-content h2{font-size:28px;margin:8px 0}
  .detail-content h3{font-size:20px;margin:28px 0 10px}
  .detail-content p{line-height:1.5;color:#555;font-size:16px}
  .interest{border-top:1px solid #ddd;padding-top:20px;margin-top:25px}
  .interest-card{display:inline-block;width:45%;vertical-align:top;padding:15px;border:1px solid #ddd;margin-right:10px;min-height:150px;background:#f9fcfd}
  .side-news{margin-top:580px;border-top:4px solid #ddd;padding-top:18px}
  .side-news h3{font-size:20px}
  .side-news input[type=email]{height:40px;width:100%;margin:10px 0;border:1px solid #ddd;padding:10px}
  .side-news button{padding:10px 24px;border:0;background:#ddd}
  @media(max-width:1000px){
    .navinner{padding:0 16px;gap:12px}.navitem{font-size:12px}
    .layout{display:block;margin:0 16px}.sidead{display:none}
    .checker,.title{max-width:890px;margin:auto}
    .mainbg{padding-top:10px}.adtop{height:150px}
    .symptom-layout{grid-template-columns:1fr 1fr}
  }
</style>
</head>
<body>
<header class="topbar">
  <nav class="navinner">
    <a class="logo btn" href="#" aria-label="WebMD home">WebMD</a>
