<div class="modalshade" id="modalshade">
  <div class="modal">
    <div class="modal-kicker">REFINE YOUR SYMPTOMS</div>
    <h2>What kind of headache?</h2>
    <div class="choices" id="choices"></div>
    <button class="modal-done btn" id="done">Done</button>
    <button class="skip btn" id="skip">Skip</button>
  </div>
</div>
<script>
(function(){
  const steps=['INFO','SYMPTOMS','CONDITIONS','DETAILS','TREATMENT'];
  let step=0, age='', sex='', query='', symptoms=[], chosenCondition='Migraine Headache';
  const stage=document.getElementById('stage'), tabs=document.getElementById('tabs');
  const choices=['pounding headache','dull headache','migraine headache','severe headache','headache in back of head','headache in front of head','headache behind ears','headache on temples','one sided headache','tension headache','repeated headaches','sudden severe headache','headache in the morning','headache','None of the above'];
  let checked=new Set();
  function drawTabs(){
    tabs.innerHTML=steps.map((s,i)=>`<div class="tab ${i===step?'active':''}">${s}</div>`).join('');
  }
  function btnrow(prev=true,nextText='Continue',disabled=false){
    return `<div class="continue-row">${prev?'<button class="stepbtn previous btn" id="prev"><span class="arrow">‹</span>Previous</button>':'<span></span>'}<button class="stepbtn next btn" id="next" ${disabled?'disabled':''}>${nextText}<span class="arrow">›</span></button></div>`;
  }
  function render(){
    drawTabs();
    if(step===0){
      stage.innerHTML=`<div class="stepcontent infoform">
        <div class="checkertitle"><span>WebMD</span> <b>Symptom Checker</b> <small>WITH BODY MAP</small></div>
        <div class="intro">Identify possible conditions and treatment related to your symptoms.<br>This tool does not provide medical advice.</div>
        <div class="fields"><div><label class="fieldlabel" for="age">Age</label><input class="ageinput" id="age" type="number" min="1" max="120" value="${age}"></div><div><span class="fieldlabel">Sex</span><div class="sexbuttons"><button class="btn ${sex==='Male'?'selected':''}" data-sex="Male">Male</button><button class="btn ${sex==='Female'?'selected':''}" data-sex="Female">Female</button></div></div></div>
      </div>${btnrow(false,'Continue',!(age&&sex))}`;
      document.getElementById('age').addEventListener('input',e=>{age=e.target.value;render()});
      document.querySelectorAll('[data-sex]').forEach(b=>b.onclick=()=>{sex=b.dataset.sex;render()});
    }else if(step===1){
      stage.innerHTML=`<div class="symptom-layout">
        <div><div class="prompt">What are your symptoms?</div>
          <div class="searchwrap"><input class="symptom-input" id="symptomInput" placeholder="Type your main symptom here" value="${query}">
            <div class="suggestions" id="suggestions"></div></div>
          ${symptoms.length?`<div class="mylist"><h3>My Symptoms</h3>${symptoms.map((s,i)=>`<div class="myitem">${s}<button class="delete btn" data-del="${i}">▤</button></div>`).join('')}</div>`:`<div class="emptybox"><div class="emptyicon"></div>No symptoms added</div>`}
        </div>
        <div class="bodyarea">
          <svg class="human" viewBox="0 0 300 440" aria-label="Body map">
            <defs><linearGradient id="skin" x1="0" x2="1"><stop stop-color="#c7d7da"/><stop offset=".48" stop-color="#eff7f8"/><stop offset="1" stop-color="#bdcdd0"/></linearGradient></defs>
            <g fill="url(#skin)" stroke="#d3e0e2" stroke-width="2">
              <ellipse cx="150" cy="39" rx="28" ry="36"/>
              <path d="M131 72 Q150 83 169 72 L177 106 Q201 110 218 127 L239 191 Q244 205 231 210 Q220 212 214 198 L191 154 L198 231 Q193 254 186 284 L195 400 Q197 420 184 422 Q173 422 171 404 L154 300 L147 300 L128 404 Q126 422 114 422 Q101 421 104 400 L112 283 Q106 253 102 231 L108 154 L84 198 Q78 212 67 208 Q56 204 62 190 L82 127 Q99 109 123 106Z"/>
              <path d="M125 79 Q150 91 175 79 L184 131 Q177 168 150 173 Q123 168 116 131Z"/>
              <path d="M115 132 Q150 150 185 132 L177 206 Q151 225 123 205Z"/>
            </g>
            <path d="M137 39h5m17 0h5M143 55q7 5 14 0" stroke="#aababc" fill="none" stroke-width="2"/>
          </svg>
          <div class="bodytools"><button class="btn" title="Body map">☏</button><button class="btn">☷</button><button class="btn">SKIN</button></div>
        </div>
      </div>${btnrow(true,'Continue',symptoms.length===0)}`;
      const inp=document.getElementById('symptomInput'), box=document.getElementById('suggestions');
      inp.addEventListener('input',()=>{query=inp.value;fillSuggestions()});
      inp.addEventListener('focus',fillSuggestions);
      function fillSuggestions(){
        const q=query.toLowerCase().trim();
        if(!q){box.classList.remove('show');return}
        const arr=['headache in front of head','headache in back of head','headache on one side of head','headache','head edema','head swelling','headache behind ears','headache on temples'];
        const matches=arr.filter(x=>x.includes(q)||q==='head');
        box.innerHTML=matches.map(item=>`<div class="suggestion"><span>${item}</span><button class="add btn" data-add="${item}">ADD</button></div>`).join('');
        box.classList.add('show');
        box.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{query='';box.classList.remove('show');if(b.dataset.add.includes('headache'))openModal();else addSymptom(b.dataset.add)});
      }
      document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{symptoms.splice(+b.dataset.del,1);render()});
    }else if(step===2){
      stage.innerHTML=`<div class="results">
        <div style="text-align:center;color:#aaa;font-size:13px;margin-bottom:70px">You received few matches. Try adding more symptoms to improve your results.</div>
        <div class="result-title">Conditions that match your symptoms</div>
        <div class="resultcols"><div>
          ${['Migraine Headache (Adult)','Tension Headache','Cluster Headache'].map((n,i)=>`<button class="condition btn" data-condition="${n}"><strong>${n}</strong><span class="match">▰ ▰ ▰ ▰　${i?'Moderate':'STRONG'} match</span></button>`).join('')}
        </div><div class="result-summary"><div>Gender　${sex||'Male'}　　Age　${age||'25'}　<a class="btn" href="#">Edit</a></div><div>My Symptoms<br><b>${symptoms.join(', ')||'headache'}</b></div><button class="stepbtn btn" style="margin-top:55px;width:300px">⟳　Start Over</button></div></div>
      </div>${btnrow(true)}`;
      document.querySelectorAll('[data-condition]').forEach(b=>b.onclick=()=>{chosenCondition=b.dataset.condition.replace(' (Adult)','');step=3;render()});
      const restart=document.querySelector('.result-summary .stepbtn');restart.onclick=()=>{step=0;age='';sex='';symptoms=[];render()};
    }else if(step===3||step===4){
      stage.innerHTML=`<div class="details">
        <div><div style="font-size:19px;margin:8px 0">Conditions that match your symptoms</div><a style="font-size:12px;color:#168bb8">UNDERSTANDING YOUR RESULTS ⓘ</a>
          ${['Migraine Headache (Adult)','Tension Headache','Cluster Headache'].map((n,i)=>`<button class="condition btn" style="margin-top:10px" data-condition="${n}"><strong>${n}</strong><span class="match">▰ ▰ ▰　${i?'Moderate':'STRONG'} match</span></button>`).join('')}
          <button class="stepbtn previous btn" id="prev" style="margin-top:15px"><span class="arrow">‹</span>Previous</button>
        </div>
        <div class="detail-content"><h2>${step===4?'Treatment Options':chosenCondition}</h2><div style="text-align:center;color:#777">Migraine | Cephalgia | Vascular headache</div>
          <div style="border-bottom:1px solid #ddd;padding:15px;text-align:center">CONDITION DETAILS　　<a class="btn" href="#">TREATMENT OPTIONS</a></div>
          <h3>${step===4?'Treatment Options':'Symptoms'}</h3><p>The most common symptoms of migraine include a dull or severe headache that may be worse on one side of the head, and a throbbing, pulsating, or pounding in the head. Other symptoms may include loss of appetite, nausea and vomiting, sensitivity to sound or light, chills, sweating, numbness or tingling, and increased urination.</p>
          <h3>How Common</h3><p>About 1 in 10 people have migraine headaches.</p>
          <h3>Overview</h3><p>Migraines are a common type of headache that can cause severe pain. They can last for a few hours or a few days and may cause throbbing, sensitivity to sound or light, nausea, or vomiting. Migraines are caused by abnormal brain activity that is triggered by certain foods, stress, or other factors... <a class="btn" href="#">read more &gt;</a></p>
          <a class="btn" href="#">Learn More about Migraine Symptoms &gt;</a>
          <div class="interest"><h3 style="text-align:center">You might be interested in</h3><div class="interest-card"><b>Migraine Headache Made Worse By</b><p>Movement, bright lights and loud sounds, smoking, and alcohol.</p></div><div class="interest-card"><b>Migraine Headache</b><p>Migraines are a common type of headache that can cause severe pain.</p></div></div>
          <h3>Risk Factors</h3><p>Risk factors for migraine include being a woman, being under age 40, and having a family history of migraine.</p>
          <h3>Diagnosed By</h3><p>To diagnose migraine, your doctor will take a medical history and do a physical exam. You may also need a CT scan, MRI, or other tests to rule out other problems.</p>
          <button class="stepbtn next btn" id="treatment">Treatment Options　›</button>
          <h3>Did You Know?</h3><p>Migraines and other vascular headaches cause spasms or dilations in the blood vessels of the brain.</p>
        </div>
      </div>${btnrow(true)}`;
      document.querySelectorAll('[data-condition]').forEach(b=>b.onclick=()=>{chosenCondition=b.dataset.condition.replace(' (Adult)','');render()});
      document.getElementById('treatment').onclick=()=>{step=4;render()};
    }else{
      stage.innerHTML=`<div class="results"><h2>Treatment Options</h2><p>Talk with your doctor about treatment options for your symptoms.</p></div>${btnrow(true,'Start Over')}`;
    }
    const prev=document.getElementById('prev');if(prev)prev.onclick=()=>{if(step>0){step--;render()}};
    const next=document.getElementById('next');if(next)next.onclick=()=>{if(!next.disabled){step=Math.min(step+1,4);render()}};
  }
  function addSymptom(s){if(!symptoms.includes(s))symptoms.push(s);render()}
  function openModal(){
    checked=new Set();
    document.getElementById('choices').innerHTML=choices.map((c,i)=>`<label class="choice"><input type="checkbox" value="${c}" ${checked.has(c)?'checked':''}>${c}</label>`).join('');
    document.querySelectorAll('#choices input').forEach(input=>input.onchange=()=>{input.checked?checked.add(input.value):checked.delete(input.value);document.getElementById('done').classList.toggle('enabled',checked.size>0)});
    document.getElementById('done').classList.remove('enabled');
